package api.publica;
import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import java.math.BigDecimal;import java.time.*;import java.util.List;import org.junit.jupiter.api.Test;import api.publica.CuentaClienteDTO.ReservaResumen;import api.publica.PagoClienteDTO.*;import negocio.*;import servicio.*;
class PagoClienteCuentaServiceTest {private ReservaResumen reserva(long id,boolean pendiente){return new ReservaResumen(id,null,pendiente?"PENDIENTE":"CONFIRMADA","Cancha",LocalDate.now().plusDays(1),LocalTime.of(10,0),LocalTime.of(11,30),new BigDecimal("25000"),BigDecimal.ZERO,new BigDecimal("6250"),new BigDecimal("25000"),LocalDateTime.now().plusMinutes(10),null,null,LocalDateTime.now(),pendiente,!pendiente,false,"ARS","mensaje");}@Test void validaPropiedadAntesDeCrear(){CuentaClienteService cuenta=mock(CuentaClienteService.class);when(cuenta.buscarReserva(3,9)).thenReturn(reserva(9,true));CreacionOrdenPagoClienteService creacion=mock(CreacionOrdenPagoClienteService.class);ConsultaOrdenPagoClienteService consulta=mock(ConsultaOrdenPagoClienteService.class);OrdenPago orden=new OrdenPago();orden.setId(4);when(creacion.crearManual(eq(9L),any(),any())).thenReturn(orden);when(consulta.convertir(orden)).thenReturn(new OrdenPagoPublica(4,9,"MANUAL","TRANSFERENCIA_MANUAL","ESPERANDO_VERIFICACION",new BigDecimal("6250"),"ARS",null,0,false,true,false,true,null,"Verificación manual"));var s=new PagoClienteCuentaService(cuenta,new CapacidadesPagoService(),creacion,consulta);assertEquals(4,s.crear(3,9,"TRANSFERENCIA_MANUAL").ordenId());verify(cuenta).buscarReserva(3,9);}@Test void reservaConfirmadaNoCreaOrden(){CuentaClienteService cuenta=mock(CuentaClienteService.class);when(cuenta.buscarReserva(3,9)).thenReturn(reserva(9,false));var s=new PagoClienteCuentaService(cuenta,new CapacidadesPagoService(),mock(CreacionOrdenPagoClienteService.class),mock(ConsultaOrdenPagoClienteService.class));assertThrows(IllegalArgumentException.class,()->s.crearManual(3,9));}}
